function sharedMelody(first, second) {
    function longest(i, j) {
        if (i === 0 || j === 0)
            return 0;
        if (first[i - 1] === second[j - 1])
            return 1 + longest(i - 1, j - 1);
        return Math.max(longest(i - 1, j), longest(i, j - 1));
    }
    return longest(first.length, second.length);
}

function sharedMelody(first, second) {
    let previous = new Array(second.length + 1).fill(0);
    for (let i = 1; i <= first.length; i++) {
        const current = new Array(second.length + 1).fill(0);
        for (let j = 1; j <= second.length; j++) {
            if (first[i - 1] === second[j - 1])
                current[j] = previous[j - 1] + 1;
            else
                current[j] = Math.max(previous[j], current[j - 1]);
        }
        previous = current;
    }
    return previous[second.length];
}
